function dir$cskh0(p){
  this.constructor(p);
  document._dir = p;
}

dir$cskh0.prototype = new DirEvent();
dir$cskh0.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
}
function getGPG() {
	var thoiGianHienTai = new Date().getTime();
	var dateObject = new Date(thoiGianHienTai);

	var gio = ('0' + dateObject.getHours()).slice(-2);
	var phut = ('0' + dateObject.getMinutes()).slice(-2);
	var giay = ('0' + dateObject.getSeconds()).slice(-2);

	var chuoiThoiGian = gio + ':' + phut + ':' + giay;

	return chuoiThoiGian
}

var currentIndex = 0;
var arrayDienThoai = ['dien_thoai','dien_thoai_new1','dien_thoai_new2','dien_thoai_new3','dien_thoai_new4','dien_thoai_new5','dien_thoai_work','dien_thoai_vc','dien_thoai_r1','dien_thoai_r2','dien_thoai_r3','dien_thoai_r4','dien_thoai_r5'];

function getNextInputValue() {
    var currentClass = arrayDienThoai[currentIndex];
    var inputs = document.querySelectorAll('input.' + currentClass);

    for (var i = 0; i < inputs.length; i++) {
        if (inputs[i].value !== "") {
            console.log("Class:", currentClass, ", Value:", inputs[i].value);
            currentIndex++;
            if (currentIndex >= arrayDienThoai.length) {
                currentIndex = 0; // Nếu đã đến cuối mảng, quay lại vị trí đầu tiên
            }
            return;
        }
    }

    currentIndex++;
    if (currentIndex >= arrayDienThoai.length) {
        currentIndex = 0; // Nếu đã đến cuối mảng, quay lại vị trí đầu tiên
    }

    // Nếu không tìm thấy ô input nào có giá trị, gọi lại hàm để kiểm tra ô input tiếp theo
    getNextInputValue();
}

function checkNextPhone() {
	getNextInputValue();
}

