function closePopups(id) {
	document.getElementById(id).style.display = 'none';
	document.removeEventListener('mouseleave', closePopupOutside);
}

// Sự kiện xử lý khi chuột rời khỏi popup
function closePopupOutside(event) {
	// Kiểm tra nếu chuột rời khỏi khu vực của popup
	if (!isMouseOverPopup(event)) {
		closePopup();
	}
}

// Hàm kiểm tra xem chuột có nằm trong khu vực của popup không
function isMouseOverPopup(event) {
	var rect = popup.getBoundingClientRect();
	return (
		event.clientX >= rect.left &&
		event.clientX <= rect.right &&
		event.clientY >= rect.top &&
		event.clientY <= rect.bottom
	);
}

// Thêm sự kiện khi click vào ngoài popup để đóng nó
document.addEventListener('click', function (event) {
	if (!popup.contains(event.target) && !isMouseOverPopup(event)) {
		closePopup();
	}
});

// Thêm sự kiện khi click vào nút đóng
var closeButton = document.getElementById('btnErrorData');
if (closeButton) {
	closeButton.addEventListener('click', function () {
		closePopup();
	});
}

// JavaScript để hiển thị và ẩn tooltip khi hover
function showTooltip(id, o) {
	var tooltip = document.getElementById(id);
	tooltip.style.display = "block";
	var p = document._dir;

	if (i % 20 === 0) {
		// Chỉ thực hiện hành động khi i là số chẵn (ví dụ: log giá trị của i)
		var dataIdValue = tooltip.getAttribute('data-id');
		var sdt = p.valForm(dataIdValue);

		var m = new Memvars();
		var controller = "loaddulieutable";
		var p = window.location.href.toString();
		p = p.substring(0, p.indexOf("Main/")) + 'AppService/EService.asmx/' + "GetData"; //GetValue

		m.val("query", 'C', "select dst, disposition, count(*) dem from lscuocgoi where dst = '" + sdt + "' AND disposition in ('ANS', 'BUSY', 'CAN', 'FAIL', 'NANS') group by dst, disposition");			

		$.ajax({
			type: "POST",
			url: p,
			header: '',
			data: JSON.stringify({ controller: controller, oMemvar: m.val() }),
			contentType: "application/json; charset=utf-8",
			dataType: "json",
			timeout: 30000,
			success: function (msg, s) {
				var data = msg.d;
				console.log(data); 
				var html = "";
				for (var item of data) {
					html += "<p>" + item.disposition + ": " + item.dem + "</p>";	
				}
				tooltip.innerHTML = html;	
			}
		});

		i++;
	} else {
		// Chỉ tăng biến i lên khi i không phải là số chẵn
		i++;
	}
}


function hideTooltip(id) {
	var tooltip = document.getElementById(id);
	tooltip.style.display = "none";
}

function copyText (str) {
var p  = document._dir;
var string = p.valForm(str);


    function handler (e){
        e.clipboardData.setData('text/plain', string);
        e.preventDefault();
        document.removeEventListener('copy', handler, true);

		$.showToast(p.msg('copypaste')+string);	
    }

    document.addEventListener('copy', handler, true);
    document.execCommand('copy');
}

