function getData() {
	var p  = document._dir;
	var myStringArray = ['ttcg_dt','ttcg_new1','ttcg_new2','ttcg_new3','ttcg_new4','ttcg_new5','ttcg_work','ttcg_vc','ttcg_r1', 'ttcg_r2', 'ttcg_r3','ttcg_r4', 'ttcg_r5', 'ttcg_t1','ttcg_t2'];
	var arrayLength = myStringArray.length;
	for (var i = 0; i < arrayLength; i++) {

		var st1 = document.querySelector("input."+myStringArray[i]).value;
		//console.log(st1)
		var st2 = document.getElementById(myStringArray[i]);
		//console.log(st2)
		var st3 = st2.className;	
		//console.log(st3)


		var t1 = document.querySelector("input."+st3);
		//console.log(t1)
		switch (st1) {
			case 'ANS':
				t1.style.backgroundColor = "#34a853";
				t1.style.color = "white";
				t1.style.borderRadius = "6px";
				break;
			case 'BUSY':
				t1.style.backgroundColor = "rgb(242,93,43)";
				t1.style.color = "white";
				t1.style.borderRadius = "6px";
				break;
			case 'FAIL':
				t1.style.backgroundColor = "rgb(30,144,255)";
				t1.style.color = "white";
				t1.style.borderRadius = "6px";
				break;
			case 'CAN':
				t1.style.backgroundColor = "rgba(255,178,0,0.7)";
				t1.style.color = "white";
				t1.style.borderRadius = "6px";
				break;
			case 'NANS':
				t1.style.backgroundColor = "rgba(255,0,0,0.7)";
				t1.style.color = "white";
				t1.style.borderRadius = "6px";
				break;
			case 'UDF':
				t1.style.backgroundColor = "#200cd9";
				t1.style.color = "white";
				t1.style.borderRadius = "6px";
				break;	
			default:
				break;
		}
	}
}

function getCdrReport() {
    var authToken = "ZCg9ISwFX9fzbACSNILV4yYTtQsy9pynFKY8GZy2uBtwISSvOp";
    var apiUrl = "https://ippbx3.tranthu.vn:2324/apibkk/apimaster/api.php?cmd=cdrreport";

    // Hàm gửi yêu cầu AJAX và xử lý phản hồi
    function sendRequest() {
        var requestData = {
            start_date: "2023-09-01 00:00:00",
            end_date: "2023-09-30 23:59:59", // Đặt end_date thành "latest" để lấy thời gian mới nhất
            field_name: "dst",
            field_pattern: "0981123123",
            status: "ALL",
            limit: 100,
            offset: 0,
            sip: 107
        };

        $.ajax({
            url: apiUrl,
            type: "POST",
            beforeSend: function(xhr) {
