function AddZero(num) {
    return (num >= 0 && num < 10) ? "0" + num : num + "";
}


function GetTimeNow() {
    var now = new Date();
    var strDateTime = 
		[
			[
				AddZero(now.getDate()), 
				AddZero(now.getMonth() + 1), 
				now.getFullYear()
			].join("/")
		]
    return strDateTime;
};


