function hasMicrophone() {
	return navigator.mediaDevices.getUserMedia({ audio: true, video: false })
    .then(function (stream) {
		// Nếu hàm được gọi thành công, có nghĩa là có microphone và người dùng đã cho phép truy cập.
		stream.getTracks().forEach(track => track.stop());
		return true;
    })
    .catch(function (error) {
		// Nếu có lỗi, có thể là do thiết bị không có microphone hoặc người dùng từ chối truy cập.
		console.error('Error accessing microphone:', error);
		return false;
    });
}


function checkMicrophoneAccess() {
    // Kiểm tra xem trình duyệt có hỗ trợ navigator.permissions không
    if (navigator.permissions) {
        // Kiểm tra trạng thái của quyền truy cập microphone
        navigator.permissions.query({ name: 'microphone' })
            .then(function (permissionStatus) {
                if (permissionStatus.state === 'granted') {
                    // Người dùng đã cho phép truy cập microphone
                    microphonePermissionGranted = true;
                } else if (permissionStatus.state === 'prompt') {
                    // Người dùng chưa quyết định, yêu cầu truy cập vào microphone
                    requestMicrophone();
                } else {
                    // Người dùng từ chối truy cập microphone
                    $.showToasts('Cuộc gọi không thể thực hiện vì bạn đã từ chối truy cập microphone.');
                }
            })
            .catch(function (error) {
                // Xử lý lỗi nếu có
                console.error('Lỗi khi kiểm tra trạng thái microphone:', error);
            });
    } else {
        // Nếu trình duyệt không hỗ trợ navigator.permissions
        $.showToasts('Bật microphone trước khi thực hiện cuộc gọi.');
    }
}

function requestMicrophone() {
    // Yêu cầu truy cập vào microphone
    navigator.mediaDevices.getUserMedia({ audio: true })
        .then(function (stream) {
            // Xử lý khi người dùng đồng ý truy cập microphone
            microphonePermissionGranted = true;
        })
        .catch(function (error) {
            // Xử lý khi người dùng từ chối hoặc có lỗi
            $.showToasts('Trình duyệt không hỗ trợ hoặc người dùng từ chối. Lỗi ' + error);

            // Yêu cầu người dùng load lại trang và bật microphone
            if (confirm('Bật microphone để thực hiện cuộc gọi. Bạn có muốn thử lại không?')) {
                // Nếu người dùng đồng ý, load lại trang
                //location.reload();
            } else {
                // Nếu người dùng không đồng ý, có thể thực hiện các hành động khác
                $.showToasts('Cuộc gọi không thể thực hiện vì bạn đã từ chối truy cập microphone.');
            }
        });
}

