function getSystemTime(format) {
    return new Promise(function(resolve, reject) {
        $.ajax({
            type: "POST",
            url: "/Main/Defaults.aspx/GetSystemTime",
            contentType: "application/json; charset=utf-8",
            dataType: "json",
            data: JSON.stringify({ format: format }),
            success: function(response) {
                var systemTime = response.d;
                resolve(systemTime);
            },
            error: function(error) {
                reject(error);
            }
        });
    });
}

function getSystemDate(format) {
    return new Promise(function(resolve, reject) {
        $.ajax({
            type: "POST",
            url: "/Main/Defaults.aspx/getSystemDate",
            contentType: "application/json; charset=utf-8",
            dataType: "json",
            data: JSON.stringify({ format: format }),
            success: function(response) {
                var systemDate = response.d;
                resolve(systemDate);
            },
            error: function(error) {
                reject(error);
            }
        });
    });
}


// YourRecordingScript.js

let mediaRecorder;
let audioChunks = [];

function startRecording(value) {
	// Lấy giá trị từ trường input
	var customValue = value;

	// Gọi hàm startRecording và truyền giá trị
	startRecordingWithCustomValue(customValue);
}

function startRecordingWithCustomValue(customValue) {
	navigator.mediaDevices.getUserMedia({ audio: true })
		.then(function (stream) {
			mediaRecorder = new MediaRecorder(stream);

			mediaRecorder.ondataavailable = function (event) {
				if (event.data.size > 0) {
					audioChunks.push(event.data);
				}
			};

			mediaRecorder.onstop = function () {
				const audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
				saveRecording(audioBlob, customValue);
				audioChunks = [];
			};

			mediaRecorder.start();
		})
		.catch(function (error) {
			console.error('Error accessing microphone:', error);
		});
}

function stopRecording() {
	if (mediaRecorder && mediaRecorder.state === 'recording') {
		mediaRecorder.stop();
	}
}

function saveRecording(audioBlob, customValue) {
	const formData = new FormData();
	formData.append('audio', audioBlob, 'recording.wav');
	formData.append('customValue', customValue);

	$.ajax({
		type: 'POST',
		url: '/AppHandler/YourSaveRecordingHandler.ashx',
		data: formData,
		processData: false,
		contentType: false,
		success: function (response) {
			console.log('Recording saved successfully:', response);
		},
		error: function (error) {
			console.error('Error saving recording:', error);
		}
	});
}

function enableButton() {
    var button = document.getElementById('myButton');
    button.removeAttribute('disabled');
    button.classList.remove('disabled');
    button.addEventListener('click', handleClick);
}

function disableButton() {
    var button = document.getElementById('myButton');
    button.setAttribute('disabled', 'true');
    button.classList.add('disabled');
    button.removeEventListener('click', handleClick);
}

function handleClick() {
	alert('Button clicked!');
}

