function scrollToBottom() {
    // Lấy tham chiếu đến tbody hoặc element chứa dòng cuối cùng của trang
    var tbody = document.getElementById('BODY_cskh0_lslncuocgoi'); // Thay 'your-tbody-id' bằng ID thật của tbody hoặc element tương ứng

    // Lấy tham chiếu đến dòng cuối cùng trong tbody
    var lastRow = tbody.rows[tbody.rows.length - 1];

    // Tính toán vị trí y của dòng cuối cùng
    var lastRowPosition = lastRow.offsetTop + lastRow.clientHeight;

    // Cuộn trang đến vị trí của dòng cuối cùng
    window.scrollTo(0, lastRowPosition);
}


