    //var query = "EXEC st_RetrieveListPhoneByTax @ma_so_thue, @action"
    m.val("ma_so_thue", 'C', masothue);
	m.val("action" , 'C', 'EDIT');


    $.ajax({
        type: "POST",
        url: ps,
        header: '',
        data: JSON.stringify({ controller: controller, oMemvar: m.val() }),
        contentType: "application/json; charset=utf-8",
        dataType: "json",
        timeout: 30000,
        cache: false, // Tắt cache
        success: function (msg, s) {
            var data = msg.d;
            console.log(data);
            // Lấy thẻ select
            var select = document.getElementById('dien_thoai_ex');
            // Trước khi đổ dữ liệu mới vào thẻ select, xóa hết các mục cũ
            select.innerHTML = "";

            // Đổ dữ liệu vào thẻ select
            data.forEach(function(item) {
                var option = document.createElement('option');
                option.value = item.dien_thoai;
                if (item.ghi_chu !== "") {
                    option.text = item.dien_thoai + " - " + item.ghi_chu + " - " + item.ghi_chu2;
                } else if (item.ghi_chu2 !== "") {
                    option.text = item.dien_thoai + " - " + item.ghi_chu2;
                }
				else {
					option.text = '';
				}
                select.appendChild(option);
            });

            // Gắn sự kiện khi thay đổi lựa chọn
            select.addEventListener('change', function() {
                var selectedIndex = select.selectedIndex;
                var selectedValue = select.options[selectedIndex].value;
                var selectedText = select.options[selectedIndex].text;
                console.log("Option đã chọn: " + selectedValue);
                console.log("Option đã chọn: " + selectedText);

                // Gọi hàm để cập nhật dữ liệu sau khi đã chọn option
                //updateData(selectedValue, mapl);


                p.valForm('dien_thoai_ex', selectedValue + " - " + selectedText.split(" - ")[1], true);
                console.log(selectedText); 


            });
            // Tự động kích hoạt sự kiện change cho option đầu tiên
            select.dispatchEvent(new Event('change'));
        },
        error: function (e) {
            console.log(e);
        }
    }); //ajax 1
}, 500);



