function setTitleBasedOnValue(val) {
	var ele = document.querySelector("input." + val);
	var value = ele.value.trim();
	ele.title = value;
}

dir$cskh0.prototype.formFieldValueChange = function(o, cF, v) {
    var p = this._dir;

  switch (cF){
	case 'ma_noi_di':
		if(p.valForm('ma_noi_di') === '') p.valForm('ten_noi_di','', true)
	break;
	case 'ma_noi_den':
		if(p.valForm('ma_noi_den') === '') p.valForm('ten_noi_den','', true)
	break;
    default:
      break;
  }
};

dir$cskh0.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir
  switch (id) {
    case 'ok':
		//$.showToast('ok');
		break;
    default:
      break;
  }
  return true;
}

dir$cskh0.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
	case 'refresh':
		if(p.options.action !== "NEW"){
		$.showToast('Đang xử lý');
		}
	return false;
	break;
	case '20':
        var p = document._dir;
	   if (p.valForm('ma_noi_di').trim() == '') {
        p.jObject('ma_noi_di').focus(); 
        return;
      }if (p.valForm('ma_noi_den').trim() == '') {
        p.jObject('ma_noi_den').focus(); 
        return;
      }
      p.showFilter("cskh0BN1", null, {_unit_id: p.valForm('unit_id'),_ma_noi_di: p.valForm('ma_noi_di'), _ten_noi_di: p.valForm('ten_noi_di'), _ma_noi_den: p.valForm('ma_noi_den'),_ten_noi_den: p.valForm('ten_noi_den')});
	 return false;
      break;
    default:
      break;
  }
  return true;
}
function dir$khdxlDisabledMasterField(p, g){
	if(p.options.action != 'NEW') {
		p.setDisabled(['ma_so_thue', 'ten_kh', 'ten_kh2', 'dia_chi','nguoi_lh', 'e_mail', 'ten_nh_kh1', 'ten_nh_kh2', 'ten_nh_kh3', 'home_page', 'ten_nh', 'ten_tt', 'gioi_han_no', 'ky_han_no', 'ten_nvbh', 'phong_kd', 'fax', 'so_tk'],true)
	}
}

css.text:

.modal-dialog-lg{min-width:1200px!important;}
.control-label.ttbaolanh, .control-label.ttcanhan, .control-label.ttsdtT1 {color: #B22222; text-decoration: underline}
.control-label.tt2, .control-label.tt, .control-label.tt3 {color: #499b98; text-decoration: underline}
.buttonimg {display: inline-block;right: 0px;cursor: pointer;position: absolute;}
.ma_td span, .ma_plkh span, .dien_giai span{color: #207d51; font-weight: 700}
.dien_thoai_nt span, .dien_thoai_nt1 span, .dien_thoai_nt2 span, .dien_thoai_nt3 span, .dien_thoai_nt4 span, .dien_thoai_nt5 span{color: #207d51; font-weight: 700}
.dien_thoai span{color: #207d51; font-weight: 700}
.input-field.dien_thoai_t1, .input-field.dien_thoai_t2 {color: #207d51; font-weight: 600}
.input-field.ten_t1, .input-field.ten_t2 {color: #207d51; font-weight: 600}

.control-label.thanh_ly, .control-label.tien_no_goc, .control-label.tien_can_tra, .control-label.tien_da_tra, .control-label.tien_lai,.control-label.tien_vay, .control-label.tien_da_tt, .control-label.ma_tthd {font-weight: bold}
.input-field.thanh_ly, .input-field.tien_can_tra, .input-field.ten_tthd {font-weight: 600; color:#B22222}
