.control-label.dien_thoai_t1, .control-label.dien_thoai_t2 {color: #207d51;font-weight: 700;}
.control-label.please {color: #B22222;}
.scroll-inner {
	overflow-x: auto;
	&::-webkit-scrollbar {
		width: 10px;
	}
	&::-webkit-scrollbar:horizontal {
		height: 5px;
	}
	&::-webkit-scrollbar-track {
		background-color: transparentize(#ccc, 0.7);
	}
	&::-webkit-scrollbar-thumb {
		border-radius: 10px;
		background: transparentize(#ccc, 0.5);
		box-shadow: inset 0 0 6px rgba(0,0,0,0.5); 
	}
}
.Click-here {
	background: transparent;
	border: none;
}
.col-fill-100 {
	min-width: 768px!important;
}
/* Ẩn tooltip ban đầu */
.tooltip-copy {
	display: none;
	position: absolute;
	background-color: #333;
	color: #fff;
	padding: 5px;
	border-radius: 4px;
	z-index: 1;
	top: -30px;
}
/* Hiển thị tooltip khi hover vào nút copy */
.copy-button:hover + .tooltip-copy {
	display: inline-block;
}
.button-copy {
	background: blanchedalmond;
	border: none;
	border-radius: 5px;
}
/* CSS để tùy chỉnh nút "+" */
.tooltip-btn {
	cursor: pointer;
	background-color: #4CAF50;
	color: white;
	font-size: 16px;
	border: none;
	border-radius: 50%;
	padding: 10px;
}
.col-30 {
	width: 30px !important;
	text-align: center;
}
.a-copy {
	background: blanchedalmond;
	border: none;
	border-radius: 5px;
	padding: 2px 3px;
}
.label-ans {
	padding: 0 30px;
	background-color: #34a853;
	border-radius: 5px;
	text-align: center;
}
.label-nans {
	padding: 0 30px;
	background-color: rgba(255,0,0,0.7);
	border-radius: 5px;
	text-align: center;
}
.label-busy {	
	padding: 0 30px;
	background-color: rgb(242,93,43);
	border-radius: 5px;
	text-align: center;
}
.label-fail {
	padding: 0 30px;
	background-color: rgb(30,144,255);
	border-radius: 5px;
	text-align: center;
}
.label-can {
	padding: 0 30px;
	background-color: rgba(255,178,0,0.7);
	border-radius: 5px;
	text-align: center;
}
.label-udf {
	padding: 0 30px;
	background-color: #200cd9;
	border-radius: 5px;
	text-align: center;
}
.label-font {
	padding: 0 30px;
	font-size: 13px;
}
.spacer {
	border-collapse: separate;
	border-spacing: 0 2px;
}
.img-recording {
	width: 90px;
	height: 60px;
	position: absolute;
	top: -20px;
	right: -30px;
	border: none;
	cursor: pointer;
}
.control-label.dien_thoai_ex {
	color: #207d51;
	font-weight: 700;
}
label.dien_thoai {
	padding: 0 !important;
}
#dien_thoai_ex {
	width: 290px;
}
